#include <bits/stdc++.h>
using namespace std;

/**
 * Utility function to compute modular inverses.
 */
vector<long long> invs(int n, long long p) {
    vector<long long> res(n);
    res[1] = 1;
    for (int i = 2; i < n; i++) {
        res[i] = (p - (p / i) * res[p % i] % p) % p;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int totalPoints, threshold, lengthMultiplier;
    cin >> totalPoints >> threshold >> lengthMultiplier;

    const long long MOD = 998244353;
    vector<long long> invs = invs(2 * totalPoints + 3, MOD);

    vector<vector<long long>> dpStates(2 * totalPoints + 1, vector<long long>(totalPoints + 1, 0));
    // Initialize starting state
    dpStates[0][1] = 1;

    for (int step = 1; step < 2 * totalPoints; step++) {
        int maxPrevIntervals = min(2 * totalPoints - step, step);
        int maxNewIntervals = min(2 * totalPoints - step - 1, step + 1);
        for (int active = 0; active <= maxPrevIntervals; active++) {
            if (dpStates[step - 1][active] != 0) {
                long long currentVal = dpStates[step - 1][active];
                if (active > 0) {
                    // Close an interval
                    dpStates[step][active - 1] = (dpStates[step][active - 1] + currentVal * active % MOD * invs[2 * totalPoints - step]) % MOD;
                }
                if (active < maxNewIntervals) {
                    // Start a new interval
                    long long ways = (2 * totalPoints - step - active) % MOD;
                    dpStates[step][active + 1] = (dpStates[step][active + 1] + currentVal * ways % MOD * invs[2 * totalPoints - step]) % MOD;
                }
            }
        }
    }

    long long result = 0;
    for (int i = 0; i < 2 * totalPoints; i++) {
        for (int j = threshold; j <= totalPoints; j++) {
            result = (result + dpStates[i][j]) % MOD;
        }
    }
    result = result * lengthMultiplier % MOD * invs[2 * totalPoints + 1] % MOD;
    cout << result << "\n";

    return 0;
}
